[
    {
        "role": "bullet",
        "segment": "Number of scenario scripts (NSS) in the use cases is a size measure that is correlated with application size and number of test cases; NSS is useful in at least two ways: as a size measure, it can feed an estimation model for predicting project effort or duration; as a test case estimate, it helps the test team prepare test cases and allocate resources for future testing activities.",
        "citations": [
            {
                "type": "source_text",
                "content": "First, they look at the product in terms of its use cases. Each use case is associated with a scenario that describes a task performed by the system. Lorenz and Kidd count the number of scenario scripts (NSS) in the use cases. They report that this measure is correlated with application size and number of test cases. For this reason, NSS is useful in at least two ways.As a size measure, it can feed an estimation model for predicting project effort or duration. As a test case estimate, it helps the test team prepare test cases and allocate resources for future testing activities.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "Number of key classes (i.e., domain classes) in the system is a size measure intended to evaluate high-level design, suggesting how much effort is needed to build the system.",
        "citations": [
            {
                "type": "source_text",
                "content": "Next, Lorenz and Kidd count the number of key classes (i.e., domain classes) in the system. This measure is intended to evaluate high-level design, suggesting how much effort is needed to build the system.",
                "img_id": null
            }
        ]
    }
]

