[
    {
        "role": "bullet",
        "segment": "- Customers/clients/users: use the requirements to understand what the system should do from a business perspective; documentation should be targeted at a business audience and describe the general purpose, scope, benefits, objectives, and goals in customer terms.",
        "citations": [
            {
                "type": "source_text",
                "content": "The requirements definition that is aimed at a business audience, such as clients, customers, and users",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "First, we outline the general purpose and scope of the system, including relevant benefits, objectives, and goals.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "- Requirements analysts / systems analysts: use requirements to elicit, capture, and validate what the customer needs; documentation should support traceability from customer needs to implemented features and facilitate validation and refinement.",
        "citations": [
            {
                "type": "source_text",
                "content": "The person performing these tasks usually goes by the title of requirements analyst or systems analyst",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "As a requirements analyst, we first work with our customers to elicit the requirements by asking questions, examining current behavior, or demonstrating similar systems.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "- Designers: treat requirements as constraints on acceptable solutions and use them to guide design decisions; documentation should clearly specify constraints and the required behavior to implement.",
        "citations": [
            {
                "type": "source_text",
                "content": "Designers treat requirements as constraints on what would be considered an acceptable solution.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "- Testers (acceptance testers): derive from the requirements a suite of acceptance tests to demonstrate to the customer that the system is as requested; documentation should map requirements to testable acceptance criteria.",
        "citations": [
            {
                "type": "source_text",
                "content": "The test team derives from the requirements a suite of acceptance tests , which will be used to demonstrate to the customer that the system being delivered is indeed what was ordered.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "- Maintenance team / Maintainers: use the requirements to ensure that enhancements do not interfere with the system's original intent; documentation should preserve the connection between requirements and system behavior for future changes.",
        "citations": [
            {
                "type": "source_text",
                "content": "The maintenance team uses the requirements to help ensure that system enhancements (repairs and new features) do not interfere with the system's original intent.",
                "img_id": null
            }
        ]
    }
]

