[
    {
        "role": "bullet",
        "segment": "a. InventorySearchByID has high cohesion because it performs a single purpose—searching inventory for a range of IDs and returning the matching records—consistent with functional cohesion where all elements are essential to a single function.",
        "citations": [
            {
                "type": "source_text",
                "content": "Our ideal is functional cohesion , where two conditions hold: all elements essential to a single function are contained in one module, and all of that module's elements are essential to the performance of that function.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "b. ProcessPurchase has low cohesion because it performs multiple unrelated responsibilities (removing from inventory, printing a receipt, and updating the log), which constitutes a module with multiple purposes.",
        "citations": [
            {
                "type": "source_text",
                "content": "The worst degree of cohesion, coincidental , is found in a module whose parts are unrelated to one another.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "c. FindSet has high cohesion (communicational cohesion) since it processes the user's request to determine the matching items and formats them for display, all related to presenting the same data set.",
        "citations": [
            {
                "type": "source_text",
                "content": "Modules that are designed around data sets in this way are communicationally cohesive .",
                "img_id": null
            }
        ],
        "type": null
    }
]

[
    {
        "role": "paragraph",
        "segment": "An egoless design review is one in which comments are directed at the process and the product, not at the participants.",
        "citations": [
            {
                "type": "source_text",
                "content": "egoless, because comments are directed at the process and the product, not at the participants",
                "img_id": null
            }
            ]
        ,
        "type": null
    },
    {
        "role": "paragraph",
        "segment": "Egoless reviews are necessary because the review process encourages and enhances communication among the diverse members of the team, and helps ensure concerns are raised about the design rather than about people.",
        "citations": [
            {
                "type": "source_text",
                "content": "The review process encourages and enhances communication among the diverse members of the team.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet_intro",
        "segment": "Ways to achieve egoless reviews:",
        "citations": [],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Use an egoless approach where criticism is of the product or the result, not the people involved.",
        "citations": [
            {
                "type": "source_text",
                "content": "The egoless team structure is democratic, and all team members vote on a decision, whether it concerns design considerations or testing techniques.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Let a moderator lead the discussion with no vested interest in the project, and have the moderator encourage discussion, act as an intermediary between opposing viewpoints, keep the discussion moving, and maintain objectivity and balance.",
        "citations": [
            {
                "type": "source_text",
                "content": "The moderator leads the discussion but has no vested interest in the project itself. He or she encourages discussion, acts as an intermediary between opposing viewpoints, keeps the discussion moving, and maintains objectivity and balance in the process.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Keep the review size small so that discussion and decision making are not hampered.",
        "citations": [
            {
                "type": "source_text",
                "content": "The total number should be kept small, so that discussion and decision making are not hampered.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Use an active design review with questions tailored to different readers, so reviewers exercise the design document rather than just reading it for problems.",
        "citations": [
            {
                "type": "source_text",
                "content": "An active design review (Parnas  and  Weiss  1985)  is  a  particularly  effective method for evaluating the quality of the SAD and determining whether it contains the right information. In an active review, reviewers exercise the design document by using it in ways that developers will use the final document in practice.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Represent diverse reader classes, so each reviewer asks questions appropriate to their use of the SAD.",
        "citations": [
            {
                "type": "source_text",
                "content": "Each reviewer represents a different class of reader and is asked questions suitable to his or her use of a SAD.",
                "img_id": null
            }
        ],
        "type": null
    }
]

