[
    {
        "role": "paragraph",
        "segment": "Cleanroom aims to certify the software with respect to the specifications and to produce zero-fault or near-zero-fault software. It uses box structures (black box, refined as a state box, and refined again as a clear box) to encourage identifying omissions in requirements early, and the clear-box specification is converted to an intended function, with a correctness theorem defining the relationship describing the correctness of each function with respect to its control structures.",
        "citations": [
            {
                "type": "source_text",
                "content": "to certify the software with respect to the specifications, rather than wait for unit testing to find the faults",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "to produce zero-fault or near-zero-fault software",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "The box structures encourage analysts to find omissions in requirements early in the life cycle",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "The clear-box specification is converted to an intended function, expressed in natural language or in mathematics, as appropriate.A correctness theorem defines a relationship, expressed as one of three correctness conditions, that describes the correctness of each intended function with respect to its control structures.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "paragraph",
        "segment": "Cleanroom differs from conventional testing by emphasizing formal verification and statistical usage testing rather than relying on unit testing. It separates development from test activities, relies on peer review instead of unit testing, and uses statistical testing based on operational scenarios, with verification through formal proofs of correctness in place of traditional unit testing.",
        "citations": [
            {
                "type": "source_text",
                "content": "The project team reviews these relationships and verifies the correctness conditions with formal proofs of correctness. For example, a program and its subproofs may look like this (Linger undated):",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "This verification takes the place of unit testing, which is not permitted.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "statistical usage testing is more than 20 times as effective at extending MTTF than is coverage testing.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "The preparation and emphasis on box structures instead of state machines. In particular, they emphasized box structures instead of state machines.",
                "img_id": null
            }
        ],
        "type": null
    }
]

